-- Datos de referencia: acciones, roles, módulos y permisos.
--
-- Son datos, pero se comportan como esquema: el código pregunta por ellos por
-- nombre (`has_permission('payouts', 'read')`, el rol `seller`) y las
-- migraciones que vienen después los necesitan para repartir permisos. Sin
-- ellos una base nueva —local o staging— arranca sin roles y nadie puede
-- entrar a nada.
--
-- Es el estado de producción al 1 de octubre de 2026, con sus mismos ids: los
-- perfiles apuntan a `roles.id`, así que tienen que coincidir para poder cargar
-- una copia de los usuarios.
--
-- En producción NO se ejecuta: está registrada como aplicada.
--
-- De acá en adelante, un rol, módulo o permiso nuevo se crea en su propia
-- migración; no se edita este archivo.

SET session_replication_role = replica;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

RESET session_replication_role;
